result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/ts-form-state/src/state.test.ts", "content": "import { describe, expect, it } from 'vitest';
import { transition, type FormState } from './state.js';

const editing: FormState = {
  status: 'editing',
  values: {},
  errors: {},
};
const filled: FormState = {
  status: 'editing',
  values: { email: 'a@b.c' },
  errors: {},
};
const submitting: FormState = { status: 'submitting', values: { email: 'a@b.c' } };

describe('legal transitions', () => {
  it('CHANGE updates values and clears/sets field errors', () => {
    const s = transition(editing, { type: 'CHANGE', field: 'email', value: 'a@b.c' });
    expect(s).toEqual({ status: 'editing', values: { email: 'a@b.c' }, errors: {} });

    const blanked = transition(filled, { type: 'CHANGE', field: 'email', value: '' });
    expect(blanked).toEqual({
      status: 'editing',
      values: { email: '' },
      errors: { email: 'email is required' },
    });
  });

  it('SUBMIT moves editing -> submitting when there are no errors', () => {
    expect(transition(filled, { type: 'SUBMIT' })).toEqual(submitting);
  });

  it('SUBMIT with validation errors stays editing', () => {
    const invalid: FormState = {
      status: 'editing',
      values: { email: '' },
      errors: { email: 'email is required' },
    };
    expect(transition(invalid, { type: 'SUBMIT' })).toBe(invalid);
  });

  it('RESOLVE moves submitting -> succeeded', () => {
    expect(transition(submitting, { type: 'RESOLVE', result: 'user-42' })).toEqual({
      status: 'succeeded',
      result: 'user-42',
    });
  });

  it('REJECT moves submitting -> failed with attempt 1', () => {
    expect(
      transition(submitting, { type: 'REJECT', error: 'server down' }),
    ).toEqual({
      status: 'failed',
      values: { email: 'a@b.c' },
      error: 'server down',
      attempt: 1,
    });
  });

  it('RETRY moves failed -> submitting with the same values', () => {
    const failed: FormState = {
      status: 'failed',
      values: { email: 'a@b.c' },
      error: 'server down',
      attempt: 1,
    };
    expect(transition(failed, { type: 'RETRY' })).toEqual(submitting);
  });

  it('EDIT_AGAIN moves succeeded -> editing with a fresh form', () => {
    const done: FormState = { status: 'succeeded', result: 'user-42' };
    expect(transition(done, { type: 'EDIT_AGAIN' })).toEqual({
      status: 'editing',
      values: {},
      errors: {},
    });
  });

  it('EDIT_AGAIN moves failed -> editing with a fresh form', () => {
    const failed: FormState = {
      status: 'failed',
      values: { email: 'a@b.c' },
      error: 'server down',
      attempt: 3,
    };
    expect(transition(failed, { type: 'EDIT_AGAIN' })).toEqual({
      status: 'editing',
      values: {},
      errors: {},
    });
  });
});

describe('illegal transitions are ignored (state returned unchanged)', () => {
  it.each([
    ['CHANGE while submitting', submitting, { type: 'CHANGE', field: 'email', value: 'x' } as const],
    ['RETRY while editing', filled, { type: 'RETRY' } as const],
    ['RESOLVE while editing', filled, { type: 'RESOLVE', result: 'r' } as const],
    ['REJECT while editing', filled, { type: 'REJECT', error: 'e' } as const],
    ['SUBMIT while submitting', submitting, { type: 'SUBMIT' } as const],
    ['EDIT_AGAIN while editing', filled, { type: 'EDIT_AGAIN' } as const],
    ['CHANGE while succeeded', { status: 'succeeded', result: 'r' } as FormState, { type: 'CHANGE', field: 'f', value: 'v' } as const],
    ['RETRY while succeeded', { status: 'succeeded', result: 'r' } as FormState, { type: 'RETRY' } as const],
    ['RESOLVE while failed', { status: 'failed', values: {}, error: 'e', attempt: 1 } as FormState, { type: 'RESOLVE', result: 'r' } as const],
  ])('%s returns the identical state object', (_name, state, event) => {
    expect(transition(state, event)).toBe(state);
  });
});
"})
