result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/ts-form-state/src/types.test.ts", "content": "import { expectTypeOf, it } from 'vitest';
import { transition, type FormState } from './state.js';

it('errors are not readable off a submitting state', () => {
  const submitting: FormState = { status: 'submitting', values: {} };

  // @ts-expect-error FormState is a union and `errors` only exists on the
  // 'editing' member, so this access must be a compile error.
  expectTypeOf(submitting.errors);

  // @ts-expect-error `result` only exists on the 'succeeded' member.
  expectTypeOf(submitting.result);

  // @ts-expect-error `attempt` only exists on the 'failed' member.
  expectTypeOf(submitting.attempt);
});

it('narrowing restores the fields', () => {
  const state: FormState = { status: 'editing', values: {}, errors: {} };
  if (state.status === 'editing') {
    expectTypeOf(state.errors).toEqualTypeOf<Record<string, string>>();
  }
});

it('unhandled status in a switch is caught via never', () => {
  const state: FormState = { status: 'submitting', values: {} };
  function assertExhaustive(s: never): void {}
  // Compiles fine: every member handled through narrowing below would be
  // needed for a real exhaustive switch; here we just pin that a non-never
  // value cannot be passed to an exhaustiveness assertion.
  // @ts-expect-error passing the full union (not narrowed to never) fails.
  assertExhaustive(state);
});
"})
