result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/ts-form-state/src/state.ts", "content": "/**
 * Form lifecycle modeled as a discriminated union.
 *
 * States:
 *   editing    — user is filling in fields (values + per-field errors)
 *   submitting — request in flight (values frozen)
 *   succeeded  — server accepted the form
 *   failed     — server rejected the form (values kept for retry)
 */

export interface EditingState {
  status: 'editing';
  values: Record<string, string>;
  errors: Record<string, string>;
}

export interface SubmittingState {
  status: 'submitting';
  values: Record<string, string>;
}

export interface SucceededState {
  status: 'succeeded';
  result: string;
}

export interface FailedState {
  status: 'failed';
  values: Record<string, string>;
  error: string;
  attempt: number;
}

export type FormState =
  | EditingState
  | SubmittingState
  | SucceededState
  | FailedState;

export type FormEvent =
  | { type: 'CHANGE'; field: string; value: string }
  | { type: 'SUBMIT' }
  | { type: 'RESOLVE'; result: string }
  | { type: 'REJECT'; error: string }
  | { type: 'RETRY' }
  | { type: 'EDIT_AGAIN' };

function validate(values: Record<string, string>): Record<string, string> {
  const errors: Record<string, string> = {};
  if (!values['email']) errors['email'] = 'email is required';
  return errors;
}

/**
 * Pure reducer for the form lifecycle. Illegal state/event pairs return the
 * state unchanged (same reference). The exhaustive switch plus the `never`
 * default make the compiler fail if a new state or event is added without
 * handling it here.
 */
export function transition(state: FormState, event: FormEvent): FormState {
  switch (state.status) {
    case 'editing': {
      switch (event.type) {
        case 'CHANGE': {
          const values = { ...state.values, [event.field]: event.value };
          const errors = validate(values);
          const relevantErrors =
            event.field in errors || event.field in state.errors
              ? { ...state.errors, [event.field]: errors[event.field] ?? '' }
              : state.errors;
          const cleanedErrors = Object.fromEntries(
            Object.entries(relevantErrors).filter(([, msg]) => msg !== ''),
          );
          return { status: 'editing', values, errors: cleanedErrors };
        }
        case 'SUBMIT': {
          if (Object.keys(state.errors).length > 0) return state;
          return { status: 'submitting', values: state.values };
        }
        // Illegal: no-op events while editing.
        case 'RESOLVE':
        case 'REJECT':
        case 'RETRY':
        case 'EDIT_AGAIN':
          return state;
      }
      break;
    }

    case 'submitting': {
      switch (event.type) {
        case 'RESOLVE':
          return { status: 'succeeded', result: event.result };
        case 'REJECT':
          return {
            status: 'failed',
            values: state.values,
            error: event.error,
            attempt: 1,
          };
        // Illegal: CHANGE/SUBMIT/RETRY/EDIT_AGAIN while submitting.
        case 'CHANGE':
        case 'SUBMIT':
        case 'RETRY':
        case 'EDIT_AGAIN':
          return state;
      }
      break;
    }

    case 'succeeded': {
      switch (event.type) {
        case 'EDIT_AGAIN':
          return { status: 'editing', values: {}, errors: {} };
        // Illegal: everything else once succeeded.
        case 'CHANGE':
        case 'SUBMIT':
        case 'RESOLVE':
        case 'REJECT':
        case 'RETRY':
          return state;
      }
      break;
    }

    case 'failed': {
      switch (event.type) {
        case 'RETRY':
          return { status: 'submitting', values: state.values };
        case 'EDIT_AGAIN':
          return { status: 'editing', values: {}, errors: {} };
        // Illegal: CHANGE/RESOLVE/SUBMIT/REJECT while failed.
        case 'CHANGE':
        case 'SUBMIT':
        case 'RESOLVE':
        case 'REJECT':
          return state;
      }
      break;
    }
  }

  // Exhaustiveness guard: if a new member is added to FormState (or a new
  // event to FormEvent left unhandled above), `state`/`event` will not be
  // assignable to `never` here and this line fails to compile.
  const unhandled: never = state.status as never;
  throw new Error(`unhandled state: ${String(unhandled)}`);
}
"})
